public String chompBalanced(char open, char close) {
    int depth = 0;
    int start = -1;
    char quote = 0;
    boolean escaped = false;

    while (!isEmpty()) {
        char c = consume();

        if (start == -1) {
            if (c == open) {
                start = pos;
                depth = 1;
            }
            continue;
        }

        if (escaped) {
            escaped = false;
            continue;
        }

        if (c == ESC) {
            escaped = true;
            continue;
        }

        if (quote != 0) {
            if (c == quote)
                quote = 0;
            continue;
        }

        if (c == '"' || c == '\'') {
            quote = c;
        } else if (c == open) {
            depth++;
        } else if (c == close && --depth == 0) {
            return queue.substring(start, pos - 1);
        }
    }

    return start == -1 ? "" : queue.substring(start, pos);
}
